function maxCandies(status, candies, keys, containedBoxes, initialBoxes) {
  const n = status.length;
  const hasBox = new Array(n).fill(false);
  const canOpen = status.map(s => s === 1);
  const opened = new Array(n).fill(false);
  const queue = [];
  let total = 0;

  for (const box of initialBoxes) {
    hasBox[box] = true;
    if (canOpen[box] && !opened[box]) {
      opened[box] = true;
      queue.push(box);
    }
  }

  let head = 0;
  while (head < queue.length) {
    const box = queue[head];
    head++;
    total += candies[box];

    for (const key of keys[box]) {
      canOpen[key] = true;
      if (hasBox[key] && !opened[key]) {
        opened[key] = true;
        queue.push(key);
      }
    }
    for (const inner of containedBoxes[box]) {
      hasBox[inner] = true;
      if (canOpen[inner] && !opened[inner]) {
        opened[inner] = true;
        queue.push(inner);
      }
    }
  }
  return total;
}

