function maxCandies(status, candies, keys, containedBoxes, initialBoxes) {
  const held = new Set(initialBoxes);
  const owned = new Set();
  const done = new Set();
  let sum = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (const b of [...held]) {
      if (done.has(b)) continue;
      if (status[b] !== 1 && !owned.has(b)) continue;
      done.add(b);
      sum += candies[b];
      keys[b].forEach(k => owned.add(k));
      containedBoxes[b].forEach(c => held.add(c));
      changed = true;
    }
  }
  return sum;
}

