function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(800, 1000) : int(1, 7);
  const maxKeys = size === 'large' ? 3 : 2;
  // Shuffle the labels; a box may only sit inside a box earlier in this order, so nesting forms a forest.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const openChance = size === 'large' ? 0.15 + rand() * 0.3 : rand();
  const status = Array.from({ length: n }, () => (rand() < openChance ? 1 : 0));
  const candies = Array.from({ length: n }, () => (size === 'large' || rand() < 0.3 ? int(1, 1000) : int(1, 9)));
  const containedBoxes = Array.from({ length: n }, () => []);
  const roots = [];
  for (let p = 0; p < n; p++) {
    const box = order[p];
    if (p > 0 && rand() < 0.85) containedBoxes[order[int(0, p - 1)]].push(box);
    else roots.push(box);
  }
  const keys = Array.from({ length: n }, () => {
    const chosen = new Set();
    const count = int(0, maxKeys);
    for (let k = 0; k < count; k++) chosen.add(int(0, n - 1));
    return [...chosen];
  });
  const initialBoxes = roots.filter(() => rand() < 0.8);
  return [status, candies, keys, containedBoxes, initialBoxes];
}
